%%%-------------------------------------------------------------------
%%% @doc
%%% Poseidon round constants and MDS matrices for finite fields:
%%% - BLS12-381 scalar field (matching Aeternity / FATE / Hades)
%%% - BN254 scalar field (matching Circomlib / Ethereum)
%%% @end
%%%-------------------------------------------------------------------
-module(ecu_poseidon_constants).

-typing([eqwalizer]).

-export([
  prime/1,
  r_f/1,
  r_p/2,
  params_c/2,
  params_m/2,
  params_c_BLS12_381/1,
  params_m_BLS12_381/1,
  params_c_bn254/1,
  params_m_bn254/1
]).

-spec prime(bls12_381 | bn254) -> non_neg_integer().
prime(bls12_381) ->
  16#73eda753299d7d483339d80809a1d80553bda402fffe5bfeffffffff00000001;
prime(bn254) ->
  16#30644e72e131a029b85045b68181585d2833e84879b9709143e1f593f0000001.

-spec r_f(bls12_381 | bn254) -> pos_integer().
r_f(_) ->
  8.

-spec r_p(bls12_381 | bn254, pos_integer()) -> pos_integer().
r_p(bls12_381, T) when T >= 2, T =< 9 ->
  lists:nth(T - 1, [56, 57, 56, 60, 60, 63, 64, 63]);
r_p(bn254, T) when T >= 2, T =< 9 ->
  lists:nth(T - 1, [56, 57, 56, 60, 60, 63, 64, 63]).

-spec params_c(bls12_381 | bn254, pos_integer()) -> [non_neg_integer()].
params_c(bls12_381, T) ->
  params_c_BLS12_381(T);
params_c(bn254, T) ->
  params_c_bn254(T).

-spec params_m(bls12_381 | bn254, pos_integer()) -> [[non_neg_integer()]].
params_m(bls12_381, T) ->
  params_m_BLS12_381(T);
params_m(bn254, T) ->
  params_m_bn254(T).

-spec params_c_BLS12_381(pos_integer()) -> [non_neg_integer()].
-spec params_m_BLS12_381(pos_integer()) -> [[non_neg_integer()]].
-spec params_c_bn254(pos_integer()) -> [non_neg_integer()].
-spec params_m_bn254(pos_integer()) -> [[non_neg_integer()]].

